// Subject: [{issueNumber}] {_action} — {_targetName}

import {
  Body,
  Button,
  Column,
  Container,
  Head,
  Html,
  Img,
  Preview,
  Row,
  Section,
  Tailwind,
  Text,
} from "jsx-email";

import { emailAsset } from "@/components/email/email-assets";
import { linearTheme } from "@/components/email/theme-linear";

interface Props {
  _logoUrl?: string;
  actorName?: string;
  _actorAvatarUrl?: string;
  _action?: string;
  _targetName?: string;
  issueNumber?: string;
  ctaLabel?: string;
  ctaHref?: string;
  _productName?: string;
}

export const NotificationLinear = ({
  _logoUrl,
  actorName = "Someone",
  _actorAvatarUrl,
  _action = "commented",
  _targetName = "your issue",
  issueNumber = "123",
  ctaLabel = "View Issue",
  ctaHref = "#",
  _productName = "Linear",
}: Props) => {
  void _logoUrl;
  void _productName;

  return (
    <Html>
      <Head />
      <Preview>New notification</Preview>
      <Tailwind>
        <Body
          style={{
            backgroundColor: linearTheme.colorBackground,
            fontFamily: linearTheme.fontFamily,
            margin: 0,
          }}
        >
          <Container
            style={{ maxWidth: linearTheme.containerWidth, padding: "32px 0" }}
          >
            <Section style={{ paddingTop: linearTheme.spacingXl }}>
              <Row>
                <Column style={{ verticalAlign: "top", width: "48px" }}>
                  {_actorAvatarUrl && (
                    <Img
                      src={_actorAvatarUrl}
                      alt={actorName}
                      style={{
                        borderRadius: "50%",
                        height: "48px",
                        width: "48px",
                      }}
                      height={48}
                      width={48}
                    />
                  )}
                </Column>
                <Column style={{ paddingLeft: "16px", verticalAlign: "top" }}>
                  <Text
                    style={{
                      color: linearTheme.colorText,
                      fontSize: linearTheme.fontSizeBase,
                      fontWeight: linearTheme.fontWeightMedium,
                      margin: 0,
                    }}
                  >
                    {actorName}
                  </Text>
                  <Text
                    style={{
                      color: linearTheme.colorTextMuted,
                      fontSize: linearTheme.fontSizeBase,
                      margin: 0,
                      marginTop: "4px",
                    }}
                  >
                    {_action}
                  </Text>
                </Column>
              </Row>

              <Text
                style={{
                  color: linearTheme.colorText,
                  fontSize: linearTheme.fontSizeXl,
                  fontWeight: linearTheme.fontWeightMedium,
                  marginBottom: linearTheme.spacingBase,
                }}
              >
                <span
                  style={{
                    backgroundColor: linearTheme.button.primary.backgroundColor,
                    borderRadius: linearTheme.borderRadius,
                    color: linearTheme.button.primary.color,
                    display: "inline-block",
                    fontSize: linearTheme.fontSizeSm,
                    marginRight: "8px",
                    padding: "4px 8px",
                  }}
                >
                  #{issueNumber}
                </span>
                {_targetName}
              </Text>

              {ctaLabel && ctaHref && (
                <Button
                  href={ctaHref}
                  width={160}
                  height={40}
                  style={{
                    backgroundColor: linearTheme.button.primary.backgroundColor,
                    borderRadius: linearTheme.button.primary.borderRadius,
                    color: linearTheme.button.primary.color,
                    display: "inline-block",
                    fontSize: linearTheme.button.primary.fontSize,
                    fontWeight: linearTheme.button.primary.fontWeight,
                    height: "auto",
                    paddingBottom: linearTheme.button.primary.paddingY,
                    paddingLeft: linearTheme.button.primary.paddingX,
                    paddingRight: linearTheme.button.primary.paddingX,
                    paddingTop: linearTheme.button.primary.paddingY,
                    textDecoration: "none",
                    width: "auto",
                  }}
                >
                  {ctaLabel}
                </Button>
              )}
            </Section>
          </Container>
        </Body>
      </Tailwind>
    </Html>
  );
};

NotificationLinear.PreviewProps = {
  _action: "commented on",
  _actorAvatarUrl: emailAsset("avatars/avatar-1.jpg"),
  _logoUrl: emailAsset("logos/logo-emailcn.png"),
  _productName: "Linear",
  _targetName: "Bug in login flow",
  actorName: "Sarah",
  ctaHref: "https://linear.app/issue/42",
  ctaLabel: "View Issue",
  issueNumber: "42",
} satisfies Props;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
